package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type DocumentQuery struct {
	OwnerID   string `json:"owner_id"`
	Category  string `json:"category"`
	SortField string `json:"sort_field"`
	SortDir   string `json:"sort_dir"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// validateSortDirection checks sort direction is safe
func validateSortDirection(dir string) string {
	if strings.ToUpper(dir) == "DESC" {
		return "DESC"
	}
	return "ASC"
}

// sanitizeIdentifier attempts to prevent injection in identifiers
func sanitizeIdentifier(id string) string {
	// Remove obvious dangerous chars but this is insufficient
	id = strings.ReplaceAll(id, ";", "")
	id = strings.ReplaceAll(id, "--", "")
	return id
}

func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var q DocumentQuery
	if err := json.NewDecoder(r.Body).Decode(&q); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Validate sort direction properly
	sortDir := validateSortDirection(q.SortDir)

	// "Sanitize" the sort field - but this is bypassable
	sortField := sanitizeIdentifier(q.SortField)

	// Parameterized WHERE clause but dynamic ORDER BY
	// The sort_field is user-controlled and injectable
	query := fmt.Sprintf(
		`SELECT id, title, content, classification FROM documents 
		 WHERE owner_id = $1 AND category = $2 
		 ORDER BY %s %s LIMIT 50`,
		sortField, sortDir,
	)

	rows, err := db.Query(query, q.OwnerID, q.Category)
	if err != nil {
		http.Error(w, "Query error", 500)
		return
	}
	defer rows.Close()

	type Doc struct {
		ID             int    `json:"id"`
		Title          string `json:"title"`
		Content        string `json:"content"`
		Classification string `json:"classification"`
	}

	var results []Doc
	for rows.Next() {
		var d Doc
		rows.Scan(&d.ID, &d.Title, &d.Content, &d.Classification)
		results = append(results, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/documents/search", searchDocuments)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("Listening on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
